import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"10、【履】 兑下乾上","description":"周易阐真 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"周易阐真 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/chanzhen/011.md","filePath":"zh/classics/chanzhen/011.md"}'),s={name:"zh/classics/chanzhen/011.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。</p></blockquote><h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><p>初九：素履，往无咎。</p><p>九二：履道坦坦，幽人贞吉。</p><p>六三：眇能视，跛能履。履虎尾，咥人，凶。武人为于大君。</p><p>九四：履虎尾，愬愬终吉。</p><p>九五：夬履，贞厉。</p><p>上九：视履考祥，其旋元吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：上天下泽，履。君子以辨上下，定民志。</p><p>履者，登进也。上乾天，下兑泽，天覆泽而泽仰天，是上下有一定之位，不得混乱，此履之象也。</p><p>君子有见于此，知形而上者谓之道，形而下者谓之器，大小有分，尊卑有别，不得以上为下，以下为上，以大为小，以小为大，以尊为卑，以卑为尊。以是辨别上下之位，定其民志，使不得妄想过履耳。阳为君，上也；阴为民，下也。能辨上下，则是非邪正已明，非礼不履，扶阳抑阴，修真化假，内念不生，外物不入，万有皆空，一切俗情尘缘之志，于是乎定矣。卦象兑为阴金，妄情也；乾为阳金，真情也。以阴履于阳下，以阳履于阴上，妄情不起，真情长存。真情者，无情之情，以无情制有情，如猫捕鼠，如汤浇雪，片饷之间，灾变为福，民志定而无败道之物，方且渐履于刚健中正，纯粹之精矣。但定民志，全在能辨上下，辨得一分，定得一分，辨得十分，定得十分，稍有些子辨不明，即有些子定不得。故圣人尽性至命之学，先要穷理也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>咥，直结反。跛，波我反。愬，音色。夬，古快反。</p><p>履者，前进也。卦德上乾健，下兑悦，阴悦于阳，有一阴进而变为纯阳之象，故谓履。此进阳防危之卦，承上比卦而来。比者，阴顺其阳也。然欲阴顺，须先进阳，进阳至于中正，而阴自顺之，此进阳之道所宜先也。</p><p>人之真阳，本来自有，不待他求，交于后天，真情昧而妄情生，于是真阳走失于外，如虎奔而寓于西，属于他家矣。虽在他家，原是我家之物，但人不肯招摄复还耳。招摄之道，不求于乾，不求于坤，不求于离，不求于坎，专求于兑。兑为少女，代坤母而行顺道，能以阴极复阳，其性和悦，和则能缓，悦则能信，缓则能渐行，信则能耐久。能缓能信，力行不怠，可以进于坚刚不坏之地，复见乾元面目，而不为假阴假阳所伤，如履虎尾不咥人，而有亨道也。</p><p>虎为咥人之物，履之最险，若能和悦履之，而不过猛，如履虎尾也。履虎尾而瞻前顾后，不即不离，循序渐进，防危虑险，火候不差，阴者可以化而为阳，阳者可以还而为纯，不但不为虎咥，而且能盗彼杀中之生气，保命全形，此进阳无阻无滞亨通之道。和悦履健，岂小补云哉!</p><p>初九，心强气壮，素信于履道者。信于履而即能履，以是往而下手修为，必将进于无咎之地矣。此志念坚固之履也。</p><p>九二，乐在其中，自有真悦，不恋假悦，一切外物不得而移之，是以履道坦坦也。坦坦之履，无贪无求，心安神静，非始终如一守贞之幽人，不能为乐道忘年之履也。</p><p>六三，愚而自用，药物不知，火候不晓，以不明为明，以不能为能，冒然行道，如眇能视，跛能履，履虎尾，咥人，自取其凶。又如武人为于大君，自招其祸。此愚而自用之履也。</p><p>九四，刚而不躁，以诚而明，以柔而用，防危虑险，如履虎尾，愬愬戒慎恐惧，不但虎不能咥，终必履于纯阳之地，而得吉。此刚而能柔之履也。</p><p>九五，刚健中正，从心所欲，不逾矩，履道果决而不犯难心。然履道至于中正，金丹已有象，须当贞一不二，以危厉自处，方无得而复失之患。此自有入无之履也。</p><p>上九，刚居柔位，视其所履之火候，考其药物之老嫩，循序而进，旋始旋终，终以全始，期以至于阴阳混合、圆成无亏而后已。此全始全终之履也。</p><p>然则进阳之道，必须刚中有柔，柔中有刚，刚柔相济，不急不缓，和悦从容为贵乎！</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
